// Prepare Input — Run Once for All Items

const CONFIG = {
  datasets: {
    labor_market: {
      description: "Labor-market records",
      fields: {
        market_record_id: { type: "keyword", groupable: false },
        job_title:        { type: "keyword", groupable: true },
        job_field:        { type: "keyword", groupable: true,
          aliases: ["حوزه شغلی", "حوزه‌های شغلی", "زمینه شغلی", "رشته شغلی"] },
        skill:            { type: "keyword", groupable: true,
          aliases: ["مهارت", "مهارت‌ها", "توانمندی"] },
        demand_score:     { type: "number",
          aliases: ["امتیاز تقاضا", "امتیاز بازار", "تقاضا"] },
        frequency:        { type: "number",
          aliases: ["فراوانی", "تعداد تکرار", "میزان تکرار"] },
        experience_level: { type: "keyword", groupable: true,
          aliases: ["سطح تجربه", "سابقه"] },
        source_type:      { type: "keyword", groupable: true,
          aliases: ["نوع منبع", "منبع داده"] }
      }
    },

    university_courses: {
      description: "University course records",
      fields: {
        course_id:       { type: "keyword", groupable: false,
          aliases: ["شناسه درس", "کد درس"] },
        course_name:     { type: "keyword", groupable: true,
          aliases: ["نام درس", "عنوان درس"] },
        course_category: { type: "keyword", groupable: true,
          aliases: ["دسته‌بندی درس", "گروه درسی"] },
        credits:         { type: "number",
          aliases: ["واحد", "واحد درسی", "تعداد واحد"] },
        skills:          { type: "keyword", groupable: true,
          aliases: ["مهارت", "مهارت‌های درس", "مهارت‌های آموزشی"] }
      }
    }
  },

  // کاتالوگ مستقل جست‌وجو — فقط برای search_elasticsearch
  searchableEntities: {
    graduate: {
      idPattern: "G####",
      examples: ["G0001", "G0123"],
      description: "University graduate records. Use search_elasticsearch with the graduate ID or name.",
      aliases: ["فارغ التحصیل", "فارغ‌التحصیل", "دانش‌آموخته", "graduate"]
    },
    course_document: {
      idPattern: "C###",
      examples: ["C001", "C123"],
      description: "Course documents by ID. Prefer search_elasticsearch for single-document lookup by course_id.",
      aliases: ["شناسه درس", "کد درس", "course id"]
    }
  },

  metricFunctions: [
    "count_documents", "value_count", "sum",
    "avg", "min", "max", "cardinality"
  ],

  operators: {
    keyword: ["eq", "neq", "in", "not_in", "exists", "not_exists"],
    number: ["eq", "neq", "gt", "gte", "lt", "lte", "between", "exists", "not_exists"]
  },

  filterLogics: ["and", "or"],
  arrayOperators: ["in", "not_in"],
  maxQuestionLength: 1000
};

const input = $input.first().json;
const question = String(input.chatInput ?? "").trim();

if (!question) {
  throw new Error("درخواست خالی است.");
}

if (question.length > CONFIG.maxQuestionLength) {
  throw new Error("طول سؤال از حد مجاز بیشتر است.");
}

// ---------- Analytics Catalog ----------
const catalog = [];

for (const [datasetId, dataset] of Object.entries(CONFIG.datasets)) {
  catalog.push(`dataset_id: ${datasetId}`);
  catalog.push(`description: ${dataset.description}`);
  catalog.push("fields:");

  for (const [fieldName, field] of Object.entries(dataset.fields)) {
    catalog.push(
      `- ${fieldName}: type=${field.type}, groupable=${field.groupable !== false}` +
      (field.aliases ? `, Persian aliases=${field.aliases.join("، ")}` : "")
    );
  }

  catalog.push("");
}

catalog.push(`metric_functions: ${CONFIG.metricFunctions.join(", ")}`);
catalog.push(`filter_logic: ${CONFIG.filterLogics.join(", ")}`);
catalog.push("sort schema: {field: string, order: 'asc'|'desc'}");

// ---------- Search Catalog (independent) ----------
const searchCatalog = [];
searchCatalog.push("SEARCHABLE ENTITIES (use tool=search_elasticsearch):");

for (const [entityId, entity] of Object.entries(CONFIG.searchableEntities)) {
  searchCatalog.push(`entity: ${entityId}`);
  searchCatalog.push(`description: ${entity.description}`);
  searchCatalog.push(`id_pattern: ${entity.idPattern}`);
  searchCatalog.push(`examples: ${entity.examples.join(", ")}`);
  searchCatalog.push(`aliases: ${entity.aliases.join("، ")}`);
  searchCatalog.push("");
}

searchCatalog.push("Rules:");
searchCatalog.push("- For graduate ID like G0001 or graduate lookup → tool=search_elasticsearch, arguments={query: \"G0001\"}");
searchCatalog.push("- For single course document by ID like C001 → tool=search_elasticsearch is allowed");
searchCatalog.push("- Do NOT invent dataset_id=university_graduates for analytics_query");
searchCatalog.push("- analytics_query only supports: labor_market, university_courses");

return [{
  json: {
    question,
    config: CONFIG,
    catalogText: catalog.join("\n"),
    searchCatalogText: searchCatalog.join("\n")
  }
}];

// Domain Gate — Run Once for All Items (نسخه بهبودیافته)

const p = $input.first().json;
const q = String(p.question ?? "");

const normalize = s => String(s ?? "")
  .normalize("NFKC")
  .replace(/ي/g, "ی")
  .replace(/ك/g, "ک")
  .replace(/[\u200c\u200b\u200e\u200f]/g, " ")
  .replace(/[۰-۹]/g, d => "۰۱۲۳۴۵۶۷۸۹".indexOf(d))
  .replace(/[٠-٩]/g, d => "٠١٢٣٤٥٦٧٨٩".indexOf(d))
  .replace(/\s+/g, " ")
  .toLowerCase()
  .trim();

const nq = normalize(q);
const tokens = new Set(nq.match(/[\p{L}\p{N}_]+/gu) ?? []);

// واژگان دامنه (گسترش‌یافته)
const exactTerms = [
  // بازار کار و شغل
  "بازار کار", "بازار شغلی", "حوزه شغلی", "حوزه های شغلی", "حوزه‌های شغلی",
  "شغل", "شغلی", "فرصت شغلی", "فرصت‌های شغلی", "موقعیت شغلی",
  "job", "jobs", "labor market", "labour market", "job field", "job_field",

  // مهارت و توانمندی
  "مهارت", "مهارت ها", "مهارت‌ها", "توانمندی", "توانمندی‌ها", "تخصص", "تخصص‌ها",
  "قابلیت", "قابلیت‌ها", "skill", "skills", "competency", "competencies",

  // تقاضا و فراوانی
  "تقاضا", "امتیاز تقاضا", "demand", "demand_score",
  "فراوانی", "تعداد تکرار", "frequency",

  // دانشگاه و درس
  "دانشگاه", "درس", "دروس", "واحد درسی", "واحد", "سرفصل", "دوره",
  "course", "courses", "university", "credit", "credits",

  // سایر
  "فارغ التحصیل", "فارغ‌التحصیل", "فارغ التحصیلان", "graduate"
];

// نشانه‌های تحلیلی (گسترش‌یافته)
const analyticalCues = [
  // پرسش و نمایش
  "چند", "تعداد", "نشان بده", "نمایش بده", "فهرست", "لیست",
  "پیدا کن", "کدام", "چه", "برترین", "رتبه", "مقایسه",

  // محاسبات
  "میانگین", "متوسط", "مجموع", "جمع", "بیشترین", "کمترین",
  "بالاتر از", "بیشتر از", "کمتر از", "حداقل", "حداکثر", "برابر",

  // گروه‌بندی
  "برای هر", "به تفکیک", "به ازای هر", "بر اساس",

  // واژگان پرتکرار مرتبط با تحلیل مهارت
  "پرتقاضا", "پر تقاضا", "مناسب", "مورد نیاز", "موردنیاز",
  "نیاز", "احتیاج", "پرکاربرد", "مهم",

  // انگلیسی
  "average", "count", "sum", "compare", "top", "highest", "lowest",
  "list", "show", "find", "group", "most", "best"
];

const hasDomain = exactTerms.some(term => {
  const t = normalize(term);
  if (t.includes(" ")) return (` ${nq} `).includes(` ${t} `);
  return tokens.has(t);
});

const hasAnalyticalIntent = analyticalCues.some(term => {
  const t = normalize(term);
  if (t.includes(" ")) return (` ${nq} `).includes(` ${t} `);
  return tokens.has(t);
});

// منطق جدید: اگر دامنه تشخیص داده شد، حتی با نشانه تحلیلی ضعیف‌تر هم عبور کند
// فقط وقتی هر دو غایب باشند رد می‌شود
const inScope = hasDomain && (hasAnalyticalIntent || hasDomain);

return [{
  json: {
    ...p,
    inScope,
    domainReason: !hasDomain
      ? "هیچ نشانه روشنی از دامنه داده‌های دانشگاه یا بازار کار پیدا نشد."
      : !hasAnalyticalIntent
        ? "درخواست مرتبط با دامنه است اما هدف تحلیلی مشخصی ندارد."
        : "درخواست در حوزه داده‌های دانشگاه یا بازار کار قرار دارد."
  }
}];

const j = $input.first().json;
const output =
  "این درخواست در محدوده تحلیل داده‌های دانشگاهی و بازار کار NexusOps قرار نمی‌گیرد. " +
  "لطفاً درباره دروس دانشگاهی، مهارت‌ها، حوزه‌های شغلی، تقاضای بازار کار یا شکاف مهارتی سؤال کنید.";

return [{ json: { output, text: output, reason: j.domainReason } }];;

// ===== Validate Plan — Run Once for All Items =====

const prep = $("Prepare Input").first().json;
const CFG = prep.config;
const question = String(prep.question ?? "").trim();
const attempt = $runIndex;
const rawInput = $input.first()?.json ?? {};

const rawText = String(
  rawInput.text ??
  rawInput.output ??
  rawInput.response ??
  rawInput.content ??
  ""
);

const MULTI_PLAN_ENABLED = true;
const MAX_PLANS = 2;

const own = (obj, key) =>
  Object.prototype.hasOwnProperty.call(obj, key);

// --------------------------------------------------
// 1. Basic configuration checks
// --------------------------------------------------

if (!CFG?.datasets || !CFG?.operators || !Array.isArray(CFG.metricFunctions)) {
  throw new Error("Prepare Input configuration is missing or invalid.");
}

if (!question) {
  throw new Error("Current question is empty.");
}

// --------------------------------------------------
// 2. Normalization
// --------------------------------------------------

function normalize(value) {
  return String(value ?? "")
    .normalize("NFKC")
    .replace(/ي/g, "ی")
    .replace(/ك/g, "ک")
    .replace(/[\u200c\u200b\u200e\u200f]/g, " ")
    .replace(/[۰-۹]/g, d => "۰۱۲۳۴۵۶۷۸۹".indexOf(d))
    .replace(/[٠-٩]/g, d => "٠١٢٣٤٥٦٧٨٩".indexOf(d))
    .replace(/٫/g, ".")
    .replace(/\s+/g, " ")
    .toLowerCase()
    .trim();
}

const nq = normalize(question);

// --------------------------------------------------
// 3. Safe JSON extraction
// --------------------------------------------------

function extractJson(text) {
  const source = String(text ?? "")
    .replace(/<think>[\s\S]*?<\/think>/gi, "")
    .replace(/```(?:json)?/gi, "")
    .trim();

  let start = -1;
  let opening = null;
  let closing = null;

  for (let i = 0; i < source.length; i++) {
    if (source[i] === "{" || source[i] === "[") {
      start = i;
      opening = source[i];
      closing = opening === "{" ? "}" : "]";
      break;
    }
  }

  if (start < 0) return null;

  const stack = [];
  let inString = false;
  let escaped = false;

  for (let i = start; i < source.length; i++) {
    const char = source[i];

    if (inString) {
      if (escaped) {
        escaped = false;
      } else if (char === "\\") {
        escaped = true;
      } else if (char === '"') {
        inString = false;
      }
      continue;
    }

    if (char === '"') {
      inString = true;
      continue;
    }

    if (char === "{" || char === "[") {
      stack.push(char);
      continue;
    }

    if (char === "}" || char === "]") {
      const expected = char === "}" ? "{" : "[";

      if (stack.pop() !== expected) return null;

      if (stack.length === 0) {
        try {
          return JSON.parse(source.slice(start, i + 1));
        } catch {
          return null;
        }
      }
    }
  }

  return null;
}

// --------------------------------------------------
// 4. Result helpers
// --------------------------------------------------

function fail(messages, extra = {}) {
  const unsupported = extra.unsupported ?? false;

  return [{
    json: {
      valid: false,
      errors: messages,
      warnings: extra.warnings ?? [],
      attempt,
      question,
      rawPlan: rawText.slice(0, 3000),
      unsupported,
      retryable: extra.retryable ?? !unsupported
    }
  }];
}

function closeNumber(a, b) {
  return Number.isFinite(a) &&
    Number.isFinite(b) &&
    Math.abs(a - b) <= 1e-9;
}

function asArray(value, name, errors) {
  if (value === undefined || value === null) return [];

  if (!Array.isArray(value)) {
    errors.push(`${name} must be an array.`);
    return [];
  }

  return value;
}

// --------------------------------------------------
// 5. Domain detection
// --------------------------------------------------

const courseTerms = [
  "درس",
  "دروس",
  "واحد درسی",
  "واحدهای درسی",
  "سرفصل",
  "course",
  "courses",
  "curriculum",
  "university courses"
];

const marketTerms = [
  "بازار کار",
  "بازار شغلی",
  "تقاضای بازار",
  "تقاضای شغلی",
  "فراوانی بازار",
  "حوزه شغلی",
  "مهارت پرتقاضا",
  "مهارت‌های پرتقاضا",
  "مهارت های پرتقاضا",
  "job market",
  "labor market",
  "labour market",
  "market demand"
];

function containsTerm(text, term) {
  const normalizedTerm = normalize(term);

  if (normalizedTerm.includes(" ")) {
    return (` ${text} `).includes(` ${normalizedTerm} `);
  }

  const tokens = new Set(
    text.match(/[\p{L}\p{N}_]+/gu) ?? []
  );

  return tokens.has(normalizedTerm);
}

function detectDomain(text) {
  const course = courseTerms.some(term => containsTerm(text, term));
  const market = marketTerms.some(term => containsTerm(text, term));

  if (course && market) return "mixed";
  if (course) return "courses";
  if (market) return "market";

  return "unknown";
}

// --------------------------------------------------
// 6. Analytics validation
// --------------------------------------------------

function validateAnalytics(input, nqText) {
  const errors = [];
  const warnings = [];

  const bad = (extra = {}) => ({
    ok: false,
    errors,
    warnings,
    unsupported: false,
    retryable: true,
    ...extra
  });

  let plan = input;

  if (
    plan.arguments &&
    typeof plan.arguments === "object" &&
    !Array.isArray(plan.arguments)
  ) {
    plan = { ...plan.arguments };
  }

  // Dataset
  const datasetId = plan.dataset_id;

  if (
    typeof datasetId !== "string" ||
    !own(CFG.datasets, datasetId)
  ) {
    errors.push(
      `Unknown dataset_id "${datasetId}". Allowed: ${Object.keys(CFG.datasets).join(", ")}`
    );
    return bad();
  }

  const fields = CFG.datasets[datasetId].fields;

  if (!fields || typeof fields !== "object") {
    errors.push(`Dataset "${datasetId}" has no valid field catalog.`);
    return bad();
  }

    // Domain consistency
  // Domain is evaluated against the current Plan's question,
  // not necessarily the original user question.
  const domain = detectDomain(nqText);

  if (domain === "mixed") {
    errors.push(
      "This Plan combines course and labor-market data. Each Plan must target one domain."
    );
    return bad({ unsupported: true, retryable: false });
  }

  if (domain === "courses" && datasetId !== "university_courses") {
    errors.push(
      'The question refers to university course data, but dataset_id is not "university_courses".'
    );
    return bad();
  }

  if (domain === "market" && datasetId !== "labor_market") {
    errors.push(
      'The question refers to labor-market data, but dataset_id is not "labor_market".'
    );
    return bad();
  }

  // Operation
  const operation = plan.operation;

  if (!["select", "count", "aggregate"].includes(operation)) {
    errors.push(`Unsupported operation "${operation}".`);
    return bad();
  }

  const groupBy = asArray(plan.group_by, "group_by", errors);
  const metricsInput = asArray(plan.metrics, "metrics", errors);
  const filtersInput = asArray(
    plan.filter_conditions,
    "filter_conditions",
    errors
  );
  const sortInput = asArray(plan.sort, "sort", errors);

  if (errors.length) return bad();

  // Group by
  const groupFields = [];

  for (const fieldName of groupBy) {
    if (
      typeof fieldName !== "string" ||
      !own(fields, fieldName)
    ) {
      errors.push(`Unknown group_by field "${fieldName}".`);
      continue;
    }

    if (fields[fieldName].groupable === false) {
      errors.push(`Field "${fieldName}" cannot be used for grouping.`);
      continue;
    }

    if (!groupFields.includes(fieldName)) {
      groupFields.push(fieldName);
    }
  }

  // Metrics
  const metrics = [];
  const aliases = new Set();

  for (let i = 0; i < metricsInput.length; i++) {
    const metric = metricsInput[i];
    const label = `metrics[${i}]`;

    if (
      !metric ||
      typeof metric !== "object" ||
      Array.isArray(metric)
    ) {
      errors.push(`${label} must be an object.`);
      continue;
    }

    if (!CFG.metricFunctions.includes(metric.function)) {
      errors.push(
        `${label}: unsupported metric function "${metric.function}".`
      );
      continue;
    }

    const fn = metric.function;
    const normalizedMetric = { function: fn };

    if (fn !== "count_documents") {
      if (
        typeof metric.field !== "string" ||
        !own(fields, metric.field)
      ) {
        errors.push(`${label}: unknown field "${metric.field}".`);
        continue;
      }

      if (
        ["avg", "sum", "min", "max"].includes(fn) &&
        fields[metric.field].type !== "number"
      ) {
        errors.push(`${label}: ${fn} requires a numeric field.`);
        continue;
      }

      normalizedMetric.field = metric.field;
    }

    let alias = String(metric.alias ?? "").trim();

    if (!alias) {
      alias = fn === "count_documents"
        ? "record_count"
        : `${fn}_${metric.field}`;
    }

    if (!/^[a-z][a-z0-9_]{0,63}$/.test(alias)) {
      errors.push(`${label}: alias must be lower_snake_case.`);
      continue;
    }

    if (
      aliases.has(alias) ||
      own(fields, alias) ||
      groupFields.includes(alias)
    ) {
      errors.push(`${label}: duplicate or conflicting alias "${alias}".`);
      continue;
    }

    aliases.add(alias);
    normalizedMetric.alias = alias;
    metrics.push(normalizedMetric);
  }

  // Operation compatibility
  if (operation === "select") {
    if (groupFields.length || metrics.length) {
      errors.push("select cannot contain group_by or metrics.");
    }
  }

  if (operation === "count") {
    if (groupFields.length || metrics.length) {
      errors.push("count cannot contain group_by or metrics.");
    }

    if (sortInput.length) {
      errors.push("sort is not supported for count.");
    }

    if (plan.limit !== undefined && plan.limit !== null) {
      errors.push("limit must not be supplied for count.");
    }
  }

  if (operation === "aggregate") {
    if (!groupFields.length) {
      errors.push(
        "Aggregate without group_by is not supported by the current AnalyticsRequest contract."
      );

      return bad({
        unsupported: true,
        retryable: false
      });
    }

    if (!metrics.length) {
      errors.push("aggregate requires at least one metric.");
    }
  }

  // Filters
  const filters = [];

  for (let i = 0; i < filtersInput.length; i++) {
    const condition = filtersInput[i];
    const label = `filter_conditions[${i}]`;

    if (
      !condition ||
      typeof condition !== "object" ||
      Array.isArray(condition)
    ) {
      errors.push(`${label} must be an object.`);
      continue;
    }

    if (
      typeof condition.field !== "string" ||
      !own(fields, condition.field)
    ) {
      errors.push(`${label}: unknown field "${condition.field}".`);
      continue;
    }

    const field = fields[condition.field];
    const allowedOperators = CFG.operators[field.type] ?? [];

    if (!allowedOperators.includes(condition.operator)) {
      errors.push(
        `${label}: operator "${condition.operator}" is not allowed for ${field.type}.`
      );
      continue;
    }

    const isArrayOperator =
      CFG.arrayOperators.includes(condition.operator);

    const isBetween = condition.operator === "between";
    const isNoValueOperator =
      ["exists", "not_exists"].includes(condition.operator);

    let rawValues;

    if (isNoValueOperator) {
      rawValues = [];
    } else if (isBetween) {
      if (
        !Array.isArray(condition.value) ||
        condition.value.length !== 2
      ) {
        errors.push(
          `${label}: between requires exactly two values [min, max].`
        );
        continue;
      }

      rawValues = condition.value;
    } else if (isArrayOperator) {
      if (
        !Array.isArray(condition.value) ||
        !condition.value.length
      ) {
        errors.push(
          `${label}: ${condition.operator} requires a non-empty array.`
        );
        continue;
      }

      rawValues = condition.value;
    } else {
      if (Array.isArray(condition.value)) {
        errors.push(
          `${label}: this operator requires a single value.`
        );
        continue;
      }

      rawValues = [condition.value];
    }

    const normalizedValues = [];
    let invalidValue = false;

    for (const rawValue of rawValues) {
      if (field.type === "number") {
        const numericValue =
          typeof rawValue === "number"
            ? rawValue
            : Number(normalize(rawValue));

        if (
          rawValue === null ||
          rawValue === "" ||
          typeof rawValue === "boolean" ||
          !Number.isFinite(numericValue)
        ) {
          errors.push(
            `${label}: value for ${condition.field} must be numeric.`
          );

          invalidValue = true;
          break;
        }

        normalizedValues.push(numericValue);
      } else {
        if (
          typeof rawValue !== "string" &&
          typeof rawValue !== "number"
        ) {
          errors.push(
            `${label}: value for ${condition.field} must be text.`
          );

          invalidValue = true;
          break;
        }

        const value = String(rawValue).trim();

        if (!value) {
          errors.push(`${label}: empty filter value.`);
          invalidValue = true;
          break;
        }

        normalizedValues.push(value);
      }
    }

    if (invalidValue) continue;

    if (
      isBetween &&
      normalizedValues[0] > normalizedValues[1]
    ) {
      errors.push(
        `${label}: between minimum cannot exceed maximum.`
      );
      continue;
    }

    const evidence = normalize(condition.evidence);

    if (!evidence || !nqText.includes(evidence)) {
      errors.push(
        `${label}: evidence must come from the current question.`
      );
      continue;
    }

    filters.push({
      field: condition.field,
      operator: condition.operator,
      value: isNoValueOperator
        ? null
        : isArrayOperator || isBetween
          ? normalizedValues
          : normalizedValues[0]
    });
  }

  // Numeric conditions must not be silently omitted.
  const numericComparators = [
    {
      patterns: [
        /(?:حداقل|at least|greater than or equal to|>=)\s*(\d+(?:\.\d+)?)/i,
        /(\d+(?:\.\d+)?)\s*(?:یا بیشتر|و بیشتر|به بالا)(?!\s*از)/i
      ],
      op: "gte"
    },
    {
      patterns: [
        /(?:حداکثر|at most|less than or equal to|<=)\s*(\d+(?:\.\d+)?)/i,
        /(\d+(?:\.\d+)?)\s*(?:یا کمتر|و کمتر|به پایین)(?!\s*از)/i
      ],
      op: "lte"
    },
    {
      patterns: [
        /(?:بیشتر از|بالاتر از|بیش از|greater than|more than|>)\s*(\d+(?:\.\d+)?)/i
      ],
      op: "gt"
    },
    {
      patterns: [
        /(?:کمتر از|پایین تر از|کم‌تر از|less than|<)\s*(\d+(?:\.\d+)?)/i
      ],
      op: "lt"
    },
    {
      patterns: [
        /(?:برابر با|مساوی با|دقیقاً|exactly|equal to|=)\s*(\d+(?:\.\d+)?)/i
      ],
      op: "eq"
    }
  ];

  const fieldMentions = [];

  for (const [fieldName, field] of Object.entries(fields)) {
    if (field.type !== "number") continue;

    const names = new Set(
      [fieldName, ...(field.aliases ?? [])].map(normalize)
    );

    for (const name of names) {
      if (!name) continue;

      let position = 0;

      while (true) {
        const index = nqText.indexOf(name, position);

        if (index === -1) break;

        fieldMentions.push({
          field: fieldName,
          name,
          start: index,
          end: index + name.length
        });

        position = index + 1;
      }
    }
  }

  fieldMentions.sort(
    (a, b) => a.start - b.start || b.name.length - a.name.length
  );

  const uniqueMentions = [];

  for (const mention of fieldMentions) {
    const overlaps = uniqueMentions.some(
      existing =>
        mention.start < existing.end &&
        mention.end > existing.start
    );

    if (!overlaps) uniqueMentions.push(mention);
  }

  const expectedConditions = [];

  for (let i = 0; i < uniqueMentions.length; i++) {
    const current = uniqueMentions[i];
    const next = uniqueMentions[i + 1];

    const segment = nqText.slice(
      current.end,
      next ? next.start : nqText.length
    );

    for (const comparator of numericComparators) {
      let matched = false;

      for (const pattern of comparator.patterns) {
        const match = segment.match(pattern);

        if (!match) continue;

        const value = Number(match[1]);

        if (!Number.isFinite(value)) continue;

        expectedConditions.push({
          field: current.field,
          operator: comparator.op,
          value
        });

        matched = true;
        break;
      }

      if (matched) break;
    }
  }

  for (const expected of expectedConditions) {
    const found = filters.some(
      filter =>
        filter.field === expected.field &&
        filter.operator === expected.operator &&
        closeNumber(Number(filter.value), expected.value)
    );

    if (!found) {
      errors.push(
        `A numeric condition from the question was omitted: ${expected.field} ${expected.operator} ${expected.value}.`
      );
    }
  }

  // Filter logic
  const filterLogic = String(
    plan.filter_logic ?? "and"
  ).toLowerCase();

  if (!CFG.filterLogics.includes(filterLogic)) {
    errors.push("filter_logic must be and or or.");
  }

  // Sort
  const sortableFields =
    operation === "aggregate"
      ? [
          ...groupFields,
          ...metrics.map(metric => metric.alias).filter(Boolean)
        ]
      : Object.keys(fields);

  const sorts = [];

  for (let i = 0; i < sortInput.length; i++) {
    const sort = sortInput[i];
    const label = `sort[${i}]`;

    if (
      !sort ||
      typeof sort !== "object" ||
      Array.isArray(sort)
    ) {
      errors.push(`${label} must be an object.`);
      continue;
    }

    if (!sortableFields.includes(sort.field)) {
      errors.push(`${label}: invalid sort field "${sort.field}".`);
      continue;
    }

    if (!["asc", "desc"].includes(sort.order)) {
      errors.push(`${label}: order must be asc or desc.`);
      continue;
    }

    sorts.push({
      field: sort.field,
      order: sort.order
    });
  }

  // Limit
  let limit;

  if (operation === "select" && plan.limit != null) {
    const requested = Number(plan.limit);

    if (
      !Number.isInteger(requested) ||
      requested < 1 ||
      requested > 1000
    ) {
      errors.push(
        "select limit must be an integer between 1 and 1000."
      );
    } else {
      limit = requested;
    }
  }

  if (operation === "aggregate" && plan.limit != null) {
    const requested = Number(plan.limit);

    if (
      !Number.isInteger(requested) ||
      requested < 1 ||
      requested > 1000
    ) {
      errors.push(
        "aggregate limit must be an integer between 1 and 1000."
      );
    } else {
      const hasTopIntent =
        /\btop\b|\bfirst\b|برترین|بیشترین|کمترین|بالاترین|پایین ترین|اولین/.test(nqText);

      if (!hasTopIntent) {
        warnings.push(
          "Aggregate limit removed because top-N was not requested."
        );
      } else {
        limit = requested;
      }
    }
  }

  // Intent checks
  const hasMetric = fn =>
    metrics.some(metric => metric.function === fn);

  if (
    /(میانگین|متوسط|average|\bavg\b|\bmean\b)/.test(nqText) &&
    !hasMetric("avg")
  ) {
    errors.push(
      "The question requests an average, but the avg metric is missing."
    );
  }

  if (
    /(مجموع(?!ه)|جمع کل|\bsum\b)/.test(nqText) &&
    !hasMetric("sum")
  ) {
    errors.push(
      "The question requests a sum, but the sum metric is missing."
    );
  }

  if (
    /(برای هر|به تفکیک|به ازای هر|per each|for each)/.test(nqText) &&
    !groupFields.length
  ) {
    errors.push(
      "The question requests grouped results, but group_by is missing."
    );
  }

  if (errors.length) return bad();

  // Exact MCP arguments
  const args = {
    dataset_id: datasetId,
    operation,
    filter_conditions: filters,
    filter_logic: filterLogic
  };

  if (groupFields.length) args.group_by = groupFields;
  if (metrics.length) args.metrics = metrics;
  if (sorts.length) args.sort = sorts;
  if (limit !== undefined) args.limit = limit;

  return {
    ok: true,
    errors: [],
    warnings,
    unsupported: false,
    retryable: false,
    args
  };
}

// --------------------------------------------------
// 7. Tool validation
// --------------------------------------------------

function validateOne(plan, nqText) {
  const base = {
    warnings: [],
    unsupported: false,
    retryable: true
  };

  if (
    !plan ||
    typeof plan !== "object" ||
    Array.isArray(plan)
  ) {
    return {
      ok: false,
      errors: ["Plan must be a JSON object."],
      ...base
    };
  }

  if (plan.unsupported_reason) {
    return {
      ok: false,
      errors: [String(plan.unsupported_reason)],
      warnings: [],
      unsupported: true,
      retryable: false
    };
  }

  if (typeof plan.tool !== "string" || !plan.tool.trim()) {
    return {
      ok: false,
      errors: ["Plan must explicitly specify a tool."],
      ...base
    };
  }

  const tool = plan.tool.trim();

  if (tool === "search_elasticsearch") {
    const query = String(
      plan.query ?? plan.arguments?.query ?? ""
    ).trim();

    if (!query) {
      return {
        ok: false,
        errors: [
          "search_elasticsearch requires a non-empty query string."
        ],
        ...base
      };
    }

    if (query.length > 100) {
      return {
        ok: false,
        errors: [
          "search_elasticsearch query must not exceed 100 characters."
        ],
        ...base
      };
    }

    if (
      /^[gc]\d{3,4}$/i.test(query) &&
      !nqText.includes(query.toLowerCase())
    ) {
      return {
        ok: false,
        errors: [
          `The ID "${query}" does not appear in the current question.`
        ],
        ...base
      };
    }

    return {
      ok: true,
      errors: [],
      warnings: [],
      unsupported: false,
      retryable: false,
      plan: {
        tool: "search_elasticsearch",
        arguments: { query }
      }
    };
  }

  if (tool === "get_top_market_skills") {
    const limit = Number(
      plan.limit ?? plan.arguments?.limit ?? 10
    );

    if (
      !Number.isInteger(limit) ||
      limit < 1 ||
      limit > 50
    ) {
      return {
        ok: false,
        errors: [
          "get_top_market_skills limit must be an integer between 1 and 50."
        ],
        ...base
      };
    }

    return {
      ok: true,
      errors: [],
      warnings: [],
      unsupported: false,
      retryable: false,
      plan: {
        tool: "get_top_market_skills",
        arguments: { limit }
      }
    };
  }

  if (tool === "get_top_skill_gaps") {
    const limit = Number(
      plan.limit ?? plan.arguments?.limit ?? 10
    );

    if (!Number.isInteger(limit) || limit < 1 || limit > 50) {
      return {
        ok: false,
        errors: ["get_top_skill_gaps limit must be an integer between 1 and 50."],
        ...base
      };
    }

    return {
      ok: true,
      errors: [],
      warnings: [],
      unsupported: false,
      retryable: false,
      plan: {
        tool: "get_top_skill_gaps",
        arguments: { limit }
      }
    };
  }

  if (tool === "get_market_skill_details") {
    const rawSkills = plan.skills ?? plan.arguments?.skills;

    if (!Array.isArray(rawSkills) || rawSkills.length === 0) {
      return {
        ok: false,
        errors: ["get_market_skill_details requires a non-empty skills array."],
        ...base
      };
    }

    const skills = [...new Set(
      rawSkills
        .filter(skill => typeof skill === "string")
        .map(skill => skill.trim())
        .filter(Boolean)
    )];

    if (skills.length !== rawSkills.length) {
      return {
        ok: false,
        errors: ["get_market_skill_details skills must contain unique non-empty strings only."],
        ...base
      };
    }

    return {
      ok: true,
      errors: [],
      warnings: [],
      unsupported: false,
      retryable: false,
      plan: {
        tool: "get_market_skill_details",
        arguments: { skills }
      }
    };
  }

  if (tool !== "analytics_query") {
    return {
      ok: false,
      errors: [`Unknown or unsupported tool: "${tool}".`],
      warnings: [],
      unsupported: true,
      retryable: false
    };
  }

  const result = validateAnalytics(plan, nqText);

  if (!result.ok) return result;

  return {
    ok: true,
    errors: [],
    warnings: result.warnings,
    unsupported: false,
    retryable: false,
    plan: {
      tool: "analytics_query",
      arguments: result.args
    }
  };
}

// --------------------------------------------------
// 8. Main entry — Single-plan + Multi-plan
// --------------------------------------------------

const parsed = extractJson(rawText);

if (
  parsed === null ||
  typeof parsed !== "object"
) {
  return fail([
    "Planner output is not a valid JSON object or array."
  ]);
}

// --------------------------------------------------
// 8.1 Deterministic override for explicit course listing
// --------------------------------------------------

function isExplicitAllCoursesRequest(text) {
  const allTerms =
    /(?:تمام(?:ی)?|همه|کلیه|همگی|all|every)/i;

  const listingTerms =
    /(?:نمایش|نمایش بده|نشان بده|لیست|فهرست|مشاهده|show|display|list)/i;

  const courseTermsPattern =
    /(?:درس|دروس|واحد(?:های)? درسی|course|courses|curriculum)/i;

  return (
    allTerms.test(text) &&
    listingTerms.test(text) &&
    courseTermsPattern.test(text)
  );
}

// --------------------------------------------------
// 8.2 Extract planner plans
// --------------------------------------------------

let plans = null;

if (Array.isArray(parsed)) {
  plans = parsed;
} else if (Array.isArray(parsed.plans)) {
  plans = parsed.plans;
}

// --------------------------------------------------
// 8.3 Deterministic override
// --------------------------------------------------

// The deterministic override applies only when the Planner
// has not explicitly produced a multi-plan structure.

if (
  plans === null &&
  detectDomain(nq) === "courses" &&
  isExplicitAllCoursesRequest(nq)
) {
  const result = validateOne({
    tool: "analytics_query",
    dataset_id: "university_courses",
    operation: "select",
    filter_conditions: [],
    filter_logic: "and",
    sort: [],
    limit: 1000
  }, nq);

  if (!result.ok) {
    return fail(result.errors, {
      unsupported: result.unsupported,
      retryable: result.retryable,
      warnings: result.warnings
    });
  }

  return [{
    json: {
      valid: true,
      errors: [],
      warnings: result.warnings,
      attempt,
      question,
      multi: false,
      unsupported: false,
      retryable: false,
      plan: result.plan
    }
  }];
}

// --------------------------------------------------
// 8.4 Single-plan compatibility
// --------------------------------------------------

if (plans === null) {
  const result = validateOne(parsed, nq);

  if (!result.ok) {
    return fail(result.errors, {
      unsupported: result.unsupported,
      retryable: result.retryable,
      warnings: result.warnings
    });
  }

  return [{
    json: {
      valid: true,
      errors: [],
      warnings: result.warnings,
      attempt,
      question,
      multi: false,
      unsupported: false,
      retryable: false,
      plan: result.plan
    }
  }];
}

// --------------------------------------------------
// 8.5 Multi-plan structure validation
// --------------------------------------------------

if (!Array.isArray(plans) || plans.length === 0) {
  return fail([
    "Planner plans array is empty or invalid."
  ]);
}

if (plans.length > MAX_PLANS) {
  return fail([
    `At most ${MAX_PLANS} plans are supported in this version.`
  ], {
    unsupported: true,
    retryable: false
  });
}

if (plans.length > 1 && !MULTI_PLAN_ENABLED) {
  return fail([
    "Multi-part requests are not enabled."
  ], {
    unsupported: true,
    retryable: false
  });
}

// --------------------------------------------------
// 8.6 Validate each Plan independently
// --------------------------------------------------

const validatedPlans = [];
const planErrors = [];
const planWarnings = [];

for (let index = 0; index < plans.length; index++) {
  const sourcePlan = plans[index];

  const planId = `plan_${index + 1}`;

  if (
    !sourcePlan ||
    typeof sourcePlan !== "object" ||
    Array.isArray(sourcePlan)
  ) {
    planErrors.push({
      plan_id: planId,
      plan_index: index,
      errors: ["Plan must be a JSON object."]
    });

    continue;
  }

  // Support both direct Plan objects and wrapped Plan objects.
  const planPayload =
    sourcePlan.plan &&
    typeof sourcePlan.plan === "object" &&
    !Array.isArray(sourcePlan.plan)
      ? sourcePlan.plan
      : sourcePlan;

  // Preserve the Planner's sub-question when provided.
  const subQuestion = String(
    sourcePlan.sub_question ??
    sourcePlan.subQuestion ??
    sourcePlan.question ??
    sourcePlan.task ??
    ""
  ).trim();

  // A mixed-domain request requires explicit Plan-level
  // questions so that evidence and intent are evaluated
  // against the correct part of the original request.
  const originalDomain = detectDomain(nq);

  if (
    originalDomain === "mixed" &&
    !subQuestion
  ) {
    planErrors.push({
      plan_id: planId,
      plan_index: index,
      errors: [
        "A mixed-domain request requires an explicit sub_question for every Plan."
      ]
    });

    continue;
  }

  const effectiveQuestion = subQuestion || question;
  const effectiveNormalizedQuestion = normalize(effectiveQuestion);

  // Validate using the current Plan's own question.
  // This preserves all existing validation rules.
  const result = validateOne(
    planPayload,
    effectiveNormalizedQuestion
  );

  if (!result.ok) {
    planErrors.push({
      plan_id: planId,
      plan_index: index,
      sub_question: effectiveQuestion,
      errors: result.errors,
      warnings: result.warnings ?? [],
      unsupported: result.unsupported ?? false,
      retryable: result.retryable ?? false
    });

    continue;
  }

  validatedPlans.push({
    plan_id: planId,
    plan_index: index,
    plan_count: plans.length,
    sub_question: effectiveQuestion,
    tool: result.plan.tool,
    plan: result.plan,
    warnings: result.warnings ?? [],
    valid: true
  });

  if (result.warnings?.length) {
    planWarnings.push({
      plan_id: planId,
      warnings: result.warnings
    });
  }
}

// --------------------------------------------------
// 8.7 Reject the entire set if any Plan is invalid
// --------------------------------------------------

// This is intentionally fail-closed for the first stage.
// Partial execution will be introduced later, after
// Split Plans and downstream nodes support per-Plan errors.

if (planErrors.length > 0) {
  return [{
    json: {
      valid: false,
      errors: [
        "One or more Plans failed validation."
      ],
      plan_errors: planErrors,
      warnings: planWarnings,
      attempt,
      question,
      multi: plans.length > 1,
      plan_count: plans.length,
      validated_plan_count: validatedPlans.length,
      unsupported: planErrors.some(
        item => item.unsupported === true
      ),
      retryable: planErrors.some(
        item => item.retryable === true
      )
    }
  }];
}

// --------------------------------------------------
// 8.8 Single-item array compatibility
// --------------------------------------------------

// A one-element array is normalized to the existing
// single-plan output contract.

if (validatedPlans.length === 1) {
  return [{
    json: {
      valid: true,
      errors: [],
      warnings: validatedPlans[0].warnings,
      attempt,
      question,
      multi: false,
      unsupported: false,
      retryable: false,
      plan: validatedPlans[0].plan
    }
  }];
}

// --------------------------------------------------
// 8.9 Multi-plan output
// --------------------------------------------------

return [{
  json: {
    valid: true,
    errors: [],
    warnings: planWarnings,
    attempt,
    question,
    multi: true,
    unsupported: false,
    retryable: false,
    plan_count: validatedPlans.length,
    plans: validatedPlans
  }
}];

// ===== Build Retry Input — Run Once for All Items =====
const v = $input.first().json;
const prep = $("Prepare Input").first().json;

return [{
  json: {
    question: prep.question,
    catalogText: prep.catalogText,
    searchCatalogText: prep.searchCatalogText,
    lastError: (v.errors ?? []).join(" | "),
    lastRaw: v.rawPlan ?? ""
  }
}];

// Error Reply — Run Once for All Items

const j = $input.first().json;

let output;

if (j.unsupported || j.retryable === false) {
  output =
    "این نوع تحلیل در نسخه فعلی موتور Analytics پشتیبانی نمی‌شود.\n" +
    "لطفاً درخواست را ساده‌تر کنید یا هر بخش را جداگانه بپرسید.";
} else if (Array.isArray(j.errors) && j.errors.length) {
  output =
    "نتوانستم درخواست را به یک پرس‌وجوی تحلیلی معتبر تبدیل کنم.\n\n" +
    "جزئیات: " + j.errors.join("؛ ");
} else {
  output =
    "اجرای پرس‌وجو روی سرویس تحلیلی با خطا مواجه شد. " +
    "این خطا به معنی صفر بودن نتایج نیست.\n\n" +
    "جزئیات فنی: " + String(j.error ?? "خطای نامشخص");
}

return [{ json: { output, text: output } }];

// MCP Parse Init — Run Once for All Items

function parseBody(body) {
  if (body && typeof body === "object") return body;

  const text = String(body ?? "").trim();
  if (!text) return null;

  // اول سعی کن مستقیم JSON باشد
  try {
    return JSON.parse(text);
  } catch {}

  // حالت SSE: دنبال خط data: بگرد
  let last = null;

  for (const line of text.split(/\r?\n/)) {
    const trimmed = line.trim();
    if (!trimmed.startsWith("data:")) continue;

    const payload = trimmed.slice(5).trim();
    if (!payload || payload === "[DONE]") continue;

    try {
      last = JSON.parse(payload);
    } catch {}
  }

  return last;
}

const r = $input.first().json;
const message = parseBody(r.body ?? r.data);
const headers = r.headers ?? {};

// نرمال‌سازی نام هدرها (ممکن است حروف بزرگ/کوچک متفاوت باشد)
const getHeader = (name) => {
  const lower = name.toLowerCase();
  for (const key of Object.keys(headers)) {
    if (key.toLowerCase() === lower) return headers[key];
  }
  return null;
};

const sessionId = getHeader("mcp-session-id");

if (
  (r.statusCode ?? 200) >= 400 ||
  !message ||
  message.error ||
  !message.result
) {
  return [{
    json: {
      ok: false,
      error: "MCP initialize failed: " +
        String(message?.error?.message ?? r.body ?? r.data ?? "Unknown error")
    }
  }];
}

const reqHeaders = {
  "Content-Type": "application/json",
  "Accept": "application/json, text/event-stream"
};

if (sessionId) {
  reqHeaders["Mcp-Session-Id"] = sessionId;
}

if (message.result.protocolVersion) {
  reqHeaders["MCP-Protocol-Version"] = message.result.protocolVersion;
}

return [{
  json: {
    ok: true,
    sessionId,
    protocolVersion: message.result.protocolVersion ?? null,
    reqHeaders
  }
}];

// ===== Build Tool Call — Run Once for All Items =====

// --------------------------------------------------
// 1. Read MCP session and all validated plans
// --------------------------------------------------

const init = $("MCP Parse Init").last()?.json;
const splitItems = $("Split Plans").all();
const prep = $("Prepare Input").first()?.json;

if (!init?.ok) {
  throw new Error("MCP session is not initialized.");
}

if (
  !init.reqHeaders ||
  typeof init.reqHeaders !== "object" ||
  Array.isArray(init.reqHeaders)
) {
  throw new Error("MCP session headers are missing or invalid.");
}

if (!Array.isArray(splitItems) || splitItems.length === 0) {
  throw new Error("No validated plans were provided.");
}

// --------------------------------------------------
// 2. Shared validation helpers
// --------------------------------------------------

const own = (obj, key) =>
  Object.prototype.hasOwnProperty.call(obj, key);

function assert(condition, message) {
  if (!condition) {
    throw new Error(message);
  }
}

function assertAllowedKeys(obj, allowedKeys, label) {
  const unexpected = Object.keys(obj).filter(
    key => !allowedKeys.includes(key)
  );

  assert(
    unexpected.length === 0,
    `${label} contains unsupported argument(s): ${unexpected.join(", ")}`
  );
}

function isPlainObject(value) {
  return (
    value !== null &&
    typeof value === "object" &&
    !Array.isArray(value)
  );
}

// --------------------------------------------------
// 3. Tool allowlist
// --------------------------------------------------

const ALLOWED_TOOLS = new Set([
  "analytics_query",
  "get_top_market_skills",
  "get_top_skill_gaps",
  "get_market_skill_details",
  "search_elasticsearch"
]);

// --------------------------------------------------
// 4. Process every validated plan independently
// --------------------------------------------------

const output = [];

for (let index = 0; index < splitItems.length; index++) {

  const split = splitItems[index].json;

  // ------------------------------------------------
  // 4.1 Validate plan structure
  // ------------------------------------------------

  if (!split?.valid) {
    throw new Error(
      `Refusing to call MCP: plan ${index + 1} is not valid.`
    );
  }

  if (
    !split.plan ||
    typeof split.plan !== "object" ||
    Array.isArray(split.plan) ||
    !split.plan.tool ||
    !split.plan.arguments ||
    typeof split.plan.arguments !== "object" ||
    Array.isArray(split.plan.arguments)
  ) {
    throw new Error(
      `Refusing to call MCP: plan ${index + 1} is malformed.`
    );
  }

  const toolName = String(split.plan.tool).trim();
  const inputArgs = split.plan.arguments;

  assert(
    ALLOWED_TOOLS.has(toolName),
    `Tool "${toolName}" is not allowed to execute.`
  );

  // ------------------------------------------------
  // 4.2 Tool-specific argument validation
  // ------------------------------------------------

  let args;

  if (toolName === "search_elasticsearch") {

    assertAllowedKeys(
      inputArgs,
      ["query"],
      "search_elasticsearch"
    );

    const query = String(inputArgs.query ?? "").trim();

    assert(
      query.length > 0,
      "search_elasticsearch requires a non-empty query."
    );

    assert(
      query.length <= 100,
      "search_elasticsearch query must not exceed 100 characters."
    );

    args = { query };
  }

  else if (toolName === "get_top_market_skills") {

    assertAllowedKeys(
      inputArgs,
      ["limit"],
      "get_top_market_skills"
    );

    const limit = inputArgs.limit;

    assert(
      Number.isInteger(limit) &&
      limit >= 1 &&
      limit <= 50,
      "get_top_market_skills limit must be an integer between 1 and 50."
    );

    args = { limit };
  }

  else if (toolName === "get_top_skill_gaps") {

    assertAllowedKeys(
      inputArgs,
      ["limit"],
      "get_top_skill_gaps"
    );

    const limit = inputArgs.limit;

    assert(
      Number.isInteger(limit) &&
      limit >= 1 &&
      limit <= 50,
      "get_top_skill_gaps limit must be an integer between 1 and 50."
    );

    args = { limit };
  }

  else if (toolName === "get_market_skill_details") {

    assertAllowedKeys(
      inputArgs,
      ["skills"],
      "get_market_skill_details"
    );

    const skills = inputArgs.skills;

    assert(
      Array.isArray(skills) &&
      skills.length > 0 &&
      skills.every(skill => typeof skill === "string" && skill.trim().length > 0),
      "get_market_skill_details requires a non-empty array of skill names."
    );

    const normalizedSkills = [...new Set(skills.map(skill => skill.trim()))];

    assert(
      normalizedSkills.length === skills.length,
      "get_market_skill_details skills must be unique."
    );

    args = { skills: normalizedSkills };
  }

  else if (toolName === "analytics_query") {

    const CFG = prep?.config;

    assert(
      CFG?.datasets &&
      CFG?.operators &&
      Array.isArray(CFG.metricFunctions),
      "Analytics configuration is missing or invalid."
    );

    const allowedKeys = [
      "dataset_id",
      "operation",
      "filter_conditions",
      "filter_logic",
      "group_by",
      "metrics",
      "sort",
      "limit"
    ];

    assertAllowedKeys(
      inputArgs,
      allowedKeys,
      "analytics_query"
    );

    const datasetId = inputArgs.dataset_id;

    assert(
      typeof datasetId === "string" &&
      own(CFG.datasets, datasetId),
      `Unknown analytics dataset "${datasetId}".`
    );

    const fields = CFG.datasets[datasetId].fields;
    const operation = inputArgs.operation;

    assert(
      ["select", "count", "aggregate"].includes(operation),
      `Unsupported analytics operation "${operation}".`
    );

    const filters = inputArgs.filter_conditions;
    const groupBy = inputArgs.group_by ?? [];
    const metrics = inputArgs.metrics ?? [];
    const sorts = inputArgs.sort ?? [];
    const filterLogic = inputArgs.filter_logic;

    assert(
      Array.isArray(filters),
      "filter_conditions must be an array."
    );

    assert(
      Array.isArray(groupBy),
      "group_by must be an array."
    );

    assert(
      Array.isArray(metrics),
      "metrics must be an array."
    );

    assert(
      Array.isArray(sorts),
      "sort must be an array."
    );

    assert(
      ["and", "or"].includes(filterLogic),
      "filter_logic must be and or or."
    );

    // Group fields
    const normalizedGroupBy = [];

    for (const fieldName of groupBy) {

      assert(
        typeof fieldName === "string" &&
        own(fields, fieldName),
        `Invalid group_by field "${fieldName}".`
      );

      assert(
        fields[fieldName].groupable !== false,
        `Field "${fieldName}" cannot be grouped.`
      );

      if (!normalizedGroupBy.includes(fieldName)) {
        normalizedGroupBy.push(fieldName);
      }
    }

    // Metrics
    const normalizedMetrics = [];
    const metricAliases = new Set();

    for (let i = 0; i < metrics.length; i++) {

      const metric = metrics[i];

      assert(
        isPlainObject(metric),
        `metrics[${i}] must be an object.`
      );

      assert(
        CFG.metricFunctions.includes(metric.function),
        `metrics[${i}] has an unsupported function.`
      );

      const fn = metric.function;
      const normalizedMetric = { function: fn };

      if (fn !== "count_documents") {

        assert(
          typeof metric.field === "string" &&
          own(fields, metric.field),
          `metrics[${i}] has an invalid field.`
        );

        if (["avg", "sum", "min", "max"].includes(fn)) {

          assert(
            fields[metric.field].type === "number",
            `${fn} requires a numeric field.`
          );
        }

        normalizedMetric.field = metric.field;
      }

      const alias = String(metric.alias ?? "").trim();

      assert(
        /^[a-z][a-z0-9_]{0,63}$/.test(alias),
        `metrics[${i}] has an invalid alias.`
      );

      assert(
        !metricAliases.has(alias) &&
        !own(fields, alias) &&
        !normalizedGroupBy.includes(alias),
        `metrics[${i}] has a duplicate or conflicting alias.`
      );

      metricAliases.add(alias);
      normalizedMetric.alias = alias;

      normalizedMetrics.push(normalizedMetric);
    }

    // Operation compatibility
    if (operation === "select") {

      assert(
        normalizedGroupBy.length === 0 &&
        normalizedMetrics.length === 0,
        "select cannot contain group_by or metrics."
      );
    }

    if (operation === "count") {

      assert(
        normalizedGroupBy.length === 0 &&
        normalizedMetrics.length === 0,
        "count cannot contain group_by or metrics."
      );

      assert(
        sorts.length === 0,
        "sort is not supported for count."
      );

      assert(
        inputArgs.limit === undefined ||
        inputArgs.limit === null,
        "limit must not be supplied for count."
      );
    }

    if (operation === "aggregate") {

      assert(
        normalizedGroupBy.length > 0,
        "aggregate requires at least one group_by field."
      );

      assert(
        normalizedMetrics.length > 0,
        "aggregate requires at least one metric."
      );
    }

    // Filters
    const normalizedFilters = [];

    for (let i = 0; i < filters.length; i++) {

      const filter = filters[i];

      assert(
        isPlainObject(filter),
        `filter_conditions[${i}] must be an object.`
      );

      assert(
        typeof filter.field === "string" &&
        own(fields, filter.field),
        `filter_conditions[${i}] has an invalid field.`
      );

      const field = fields[filter.field];
      const allowedOperators = CFG.operators[field.type] ?? [];

      assert(
        allowedOperators.includes(filter.operator),
        `filter_conditions[${i}] has an unsupported operator.`
      );

      const isBetween = filter.operator === "between";
      const isArrayOperator =
        CFG.arrayOperators.includes(filter.operator);
      const isNoValueOperator =
        ["exists", "not_exists"].includes(filter.operator);

      let values;

      if (isNoValueOperator) {
        values = [];
      } else if (isBetween) {

        assert(
          Array.isArray(filter.value) &&
          filter.value.length === 2,
          `filter_conditions[${i}] between requires two values.`
        );

        values = filter.value;
      }

      else if (isArrayOperator) {

        assert(
          Array.isArray(filter.value) &&
          filter.value.length > 0,
          `filter_conditions[${i}] requires a non-empty array.`
        );

        values = filter.value;
      }

      else {

        assert(
          !Array.isArray(filter.value),
          `filter_conditions[${i}] requires a single value.`
        );

        values = [filter.value];
      }

      const normalizedValues = values.map(value => {

        if (field.type === "number") {

          const number = Number(value);

          assert(
            value !== null &&
            value !== "" &&
            typeof value !== "boolean" &&
            Number.isFinite(number),
            `filter_conditions[${i}] requires numeric values.`
          );

          return number;
        }

        assert(
          typeof value === "string" ||
          typeof value === "number",
          `filter_conditions[${i}] requires text values.`
        );

        const text = String(value).trim();

        assert(
          text.length > 0,
          `filter_conditions[${i}] contains an empty value.`
        );

        return text;
      });

      if (isBetween) {

        assert(
          normalizedValues[0] <= normalizedValues[1],
          `filter_conditions[${i}] has an invalid between range.`
        );
      }

      normalizedFilters.push({
        field: filter.field,
        operator: filter.operator,
        value: isNoValueOperator
          ? null
          : isBetween || isArrayOperator
            ? normalizedValues
            : normalizedValues[0]
      });
    }

    // Sort
    const normalizedSorts = [];

    for (let i = 0; i < sorts.length; i++) {

      const sort = sorts[i];

      assert(
        isPlainObject(sort),
        `sort[${i}] must be an object.`
      );

      assert(
        typeof sort.field === "string",
        `sort[${i}] has an invalid field.`
      );

      if (operation === "aggregate") {
        const metricAliasSet = new Set(
          normalizedMetrics.map(metric => metric.alias)
        );

        assert(
          normalizedGroupBy.includes(sort.field) ||
          metricAliasSet.has(sort.field),
          `sort[${i}] must use a group_by field or metric alias.`
        );
      } else {
        assert(
          own(fields, sort.field),
          `sort[${i}] has an invalid field.`
        );
      }

      assert(
        ["asc", "desc"].includes(sort.order),
        `sort[${i}] order must be asc or desc.`
      );

      normalizedSorts.push({
        field: sort.field,
        order: sort.order
      });
    }

    // Limit
    let normalizedLimit;

    if (
      operation !== "count" &&
      inputArgs.limit !== undefined &&
      inputArgs.limit !== null
    ) {

      const limit = inputArgs.limit;

      assert(
        Number.isInteger(limit) &&
        limit >= 1 &&
        limit <= 1000,
        `${operation} limit must be an integer between 1 and 1000.`
      );

      normalizedLimit = limit;
    }

    // Rebuild exact MCP arguments
    args = {
      dataset_id: datasetId,
      operation,
      filter_conditions: normalizedFilters,
      filter_logic: filterLogic
    };

    if (normalizedGroupBy.length) {
      args.group_by = normalizedGroupBy;
    }

    if (normalizedMetrics.length) {
      args.metrics = normalizedMetrics;
    }

    if (normalizedSorts.length) {
      args.sort = normalizedSorts;
    }

    if (normalizedLimit !== undefined) {
      args.limit = normalizedLimit;
    }
  }

  // ------------------------------------------------
  // 4.3 Build independent JSON-RPC request
  // ------------------------------------------------

  // Each plan receives a unique numeric JSON-RPC ID.
  const rpcId = index + 1;

  const rpcBody = {
    jsonrpc: "2.0",
    id: rpcId,
    method: "tools/call",
    params: {
      name: toolName,
      arguments: args
    }
  };

  // ------------------------------------------------
  // 4.4 Preserve plan metadata
  // ------------------------------------------------

  output.push({
    json: {
      reqHeaders: init.reqHeaders,
      rpcBody,
      selectedTool: toolName,

      rpcId,

      planIndex: split.planIndex ?? index,
      planCount: split.planCount ?? splitItems.length,
      planId: split.planId ?? `plan_${index + 1}`,

      subQuestion:
        split.subQuestion ??
        split.question ??
        prep?.question,

      question:
        split.question ??
        prep?.question
    }
  });
}

// --------------------------------------------------
// 5. Return all MCP requests
// --------------------------------------------------

return output;

// MCP Parse Result — Run Once for All Items

function parseBody(body) {
  if (body && typeof body === "object") return body;

  const text = String(body ?? "").trim();
  if (!text) return null;

  // Direct JSON response
  try {
    return JSON.parse(text);
  } catch {}

  // SSE response
  let last = null;

  for (const line of text.split(/\r?\n/)) {
    const trimmed = line.trim();

    if (!trimmed.startsWith("data:")) continue;

    const payload = trimmed.slice(5).trim();

    if (!payload || payload === "[DONE]") continue;

    try {
      last = JSON.parse(payload);
    } catch {}
  }

  return last;
}

function decodeNested(value, depth = 0) {
  if (depth > 3) return value;

  if (typeof value === "string") {
    try {
      return decodeNested(JSON.parse(value), depth + 1);
    } catch {
      return value;
    }
  }

  if (value && typeof value === "object" && !Array.isArray(value)) {
    if (typeof value.result === "string") {
      return {
        ...value,
        result: decodeNested(value.result, depth + 1)
      };
    }
  }

  return value;
}

function parseItem(r, index) {
  const body = r.body ?? r.data;
  const message = parseBody(body);

  const metadata = {
    itemIndex: index,
    rpcId: r.rpcId ?? message?.id ?? null,
    planIndex: r.planIndex ?? null,
    planCount: r.planCount ?? null,
    planId: r.planId ?? null,
    subQuestion: r.subQuestion ?? null,
    question: r.question ?? null,
    tool: r.selectedTool ?? r.tool ?? r.toolName ?? null,
    selectedTool: r.selectedTool ?? null,
    requestArguments: r.requestArguments ?? {},
    requestBody: r.requestBody ?? null
  };

  function bad(error) {
    return {
      json: {
        ...metadata,
        ok: false,
        error
      }
    };
  }

  const statusCode = Number(r.statusCode ?? 200);

  if (statusCode >= 400) {
    return bad(
      `MCP HTTP ${statusCode}: ${String(body ?? "").slice(0, 500)}`
    );
  }

  if (!message) {
    return bad("MCP response could not be parsed.");
  }

  if (message.error) {
    return bad(
      `MCP JSON-RPC error ${message.error.code}: ${message.error.message}`
    );
  }

  const result = message.result ?? {};

  const textContent = Array.isArray(result.content)
    ? result.content
        .filter(item => item.type === "text")
        .map(item => item.text)
        .join("\n")
    : "";

  if (result.isError) {
    return bad(
      `MCP tool execution error: ${textContent || "Unknown tool error"}`
    );
  }

  let data = result.structuredContent;

  if (data === undefined) {
    data = textContent || result;
  }

  data = decodeNested(data);

  if (data === null || data === undefined || data === "") {
    return bad("MCP returned no readable result.");
  }

  return {
    json: {
      ...metadata,
      ok: true,
      data
    }
  };
}

// Pair every HTTP response with its originating MCP request.
// JSON-RPC id is the primary key; input order is the fallback.
const items = $input.all();
const requests = $("Build Tool Call").all().map(item => item.json);

return items.map((item, index) => {
  const response = item.json ?? {};
  const message = parseBody(response.body ?? response.data);
  const rpcId = response.rpcId ?? message?.id ?? null;

  const request =
    requests.find(candidate => candidate.rpcId === rpcId) ??
    requests[index] ??
    {};

  const enriched = {
    ...response,
    rpcId,
    planIndex: request.planIndex ?? index,
    planCount: request.planCount ?? requests.length,
    planId: request.planId ?? `plan_${index + 1}`,
    subQuestion: request.subQuestion ?? null,
    question: request.question ?? null,
    selectedTool: request.selectedTool ?? null,
    requestArguments: request.rpcBody?.params?.arguments ?? {},
    requestBody: request.rpcBody ?? null
  };

  try {
    return parseItem(enriched, index);
  } catch (error) {
    return {
      json: {
        itemIndex: index,
        rpcId,
        planIndex: enriched.planIndex,
        planCount: enriched.planCount,
        planId: enriched.planId,
        subQuestion: enriched.subQuestion,
        question: enriched.question,
        selectedTool: enriched.selectedTool,
        requestArguments: enriched.requestArguments,
        ok: false,
        error: error.message || String(error)
      }
    };
  }
});

// ============================================================
// Format Result — Run Once for All Items
// NexusOps | Defensive, Extensible MCP Result Normalizer
// ============================================================

// ---------------- Configuration ----------------
const MAX_SHOWN = 50;
const MAX_SAMPLE = 10;
const MAX_RAW_LENGTH = 8000;

// ---------------- Input Collection ----------------
const inputItems = $input.all();
const buildItems = $("Build Tool Call").all();

if (!inputItems.length) {
  throw new Error("Format Result received no input items.");
}

if (!buildItems.length) {
  throw new Error("Format Result could not find Build Tool Call output.");
}

// ---------------- General Utilities ----------------
const isObject = (value) =>
  value !== null &&
  typeof value === "object" &&
  !Array.isArray(value);

const parseJSON = (value) => {
  if (typeof value !== "string") return value;

  const trimmed = value.trim();
  if (!trimmed) return value;

  try {
    return JSON.parse(trimmed);
  } catch {
    return value;
  }
};

const toDisplay = (value) => {
  if (value === null || value === undefined) return "";
  if (Array.isArray(value)) return value.map(toDisplay).join(", ");
  if (isObject(value)) return JSON.stringify(value);
  return String(value);
};

const escapeCell = (value) =>
  toDisplay(value)
    .replace(/\|/g, "\\|")
    .replace(/\r?\n/g, " ")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");

const markdownTable = (columns, rows, maxRows = MAX_SHOWN) => {
  if (!columns.length) return "(بدون ستون قابل نمایش)";

  if (!rows.length) return "(بدون ردیف)";

  return [
    "| " + columns.map(escapeCell).join(" | ") + " |",
    "|" + columns.map(() => "---").join("|") + "|",
    ...rows.slice(0, maxRows).map((row) =>
      "| " +
      columns.map((column) => escapeCell(row[column])).join(" | ") +
      " |"
    )
  ].join("\n");
};

const getColumns = (rows, preferred = []) => {
  const keys = new Set();

  for (const row of rows) {
    if (isObject(row)) {
      Object.keys(row).forEach((key) => keys.add(key));
    }
  }

  return [
    ...preferred.filter((key) => keys.has(key)),
    ...[...keys].filter((key) => !preferred.includes(key))
  ];
};

const safeNumber = (value) => {
  if (typeof value === "number" && Number.isFinite(value)) {
    return value;
  }

  if (
    typeof value === "string" &&
    value.trim() !== "" &&
    Number.isFinite(Number(value))
  ) {
    return Number(value);
  }

  return null;
};

const normalizeRows = (rows) => {
  if (!Array.isArray(rows)) return null;

  return rows.map((row) => {
    if (!isObject(row)) return { value: row };

    if (isObject(row._source)) {
      return {
        ...row._source,
        ...(row._id !== undefined ? { _id: row._id } : {}),
        ...(row._score !== undefined ? { _score: row._score } : {})
      };
    }

    return row;
  });
};

// ---------------- MCP Response Normalization ----------------
function unwrapResponse(response) {
  if (!isObject(response)) {
    return {
      data: response,
      raw: response,
      metadata: null
    };
  }

  let data = response.data ?? response.structuredContent ?? response;
  data = parseJSON(data);

  // MCP text-content response support
  if (isObject(data) && Array.isArray(data.content)) {
    const textBlock = data.content.find(
      (item) => isObject(item) && item.type === "text"
    );

    if (textBlock?.text !== undefined) {
      const parsedText = parseJSON(textBlock.text);

      if (parsedText !== textBlock.text) {
        data = parsedText;
      }
    }
  }

  // Unwrap only the outer MCP envelope.
  // Preserve the analytics response and its metadata.
  if (
    isObject(data) &&
    isObject(data.result) &&
    (
      data.result.status !== undefined ||
      data.result.dataset_id !== undefined ||
      data.result.operation !== undefined
    )
  ) {
    data = data.result;
  }

  return {
    data,
    raw: response,
    metadata: isObject(data?.metadata) ? data.metadata : null
  };
}

// ---------------- Search Result Renderer ----------------
function renderSearch(data, args) {
  if (!isObject(data) || !Array.isArray(data.results)) {
    return null;
  }

  const results = data.results;
  const totalReturned =
    safeNumber(data.total_returned) ?? results.length;

  const queryText = data.query ?? args.query ?? "";

  if (!results.length) {
    return {
      countValue: 0,
      rowCount: 0,
      totalRecords: totalReturned,
      shown: 0,
      columns: [],
      rows: [],
      tableMarkdown: "هیچ رکوردی برای این جست‌وجو یافت نشد.",
      extra: { query: queryText }
    };
  }

  const graduateHits = results.filter(
    (item) => item.index === "university_graduates"
  );

  const courseRecordHits = results.filter(
    (item) => item.index === "course_graduate_records"
  );

  const parts = [];

  // Graduate profile
  for (const hit of graduateHits) {
    const graduate = isObject(hit.data) ? hit.data : {};

    parts.push("### مشخصات فارغ‌التحصیل");

    const fields = [
      "graduate_id",
      "major",
      "graduation_year",
      "study_level",
      "job_title",
      "job_field",
      "employment_months",
      "career_relevance",
      "additional_training",
      "additional_skills"
    ];

    const profileRows = fields.map((field) => ({
      field,
      value: graduate[field]
    }));

    parts.push(
      markdownTable(
        ["field", "value"],
        profileRows
      )
    );
  }

  // Course-graduate records
  if (courseRecordHits.length) {
    const rows = courseRecordHits.map((hit) => {
      const item = isObject(hit.data) ? hit.data : {};
      return {
        course_id: item.course_id,
        course_name: item.course_name,
        course_relevance: item.course_relevance,
        skill_transfer: item.skill_transfer,
        graduate_satisfaction: item.graduate_satisfaction,
        related_skills: item.related_skills
      };
    });

    parts.push("### سوابق درسی مرتبط");

    parts.push(
      markdownTable(
        [
          "course_id",
          "course_name",
          "course_relevance",
          "skill_transfer",
          "graduate_satisfaction",
          "related_skills"
        ],
        rows
      )
    );
  }

  // Generic indexed-document support
  const specializedCount =
    graduateHits.length + courseRecordHits.length;

  if (specializedCount !== results.length) {
    const genericRows = results
      .filter(
        (item) =>
          item.index !== "university_graduates" &&
          item.index !== "course_graduate_records"
      )
      .map((item) => ({
        index: item.index,
        id: item.id,
        score: item.score,
        ...(isObject(item.data) ? item.data : {})
      }));

    if (genericRows.length) {
      parts.push("### سایر رکوردهای یافت‌شده");

      parts.push(
        markdownTable(
          getColumns(genericRows, ["index", "id", "score"]),
          genericRows
        )
      );
    }
  }

  return {
    countValue: null,
    rowCount: results.length,
    totalRecords: totalReturned,
    shown: Math.min(results.length, MAX_SHOWN),
    columns: [],
    rows: results.slice(0, MAX_SAMPLE),
    tableMarkdown: parts.join("\n\n"),
    extra: {
      query: queryText,
      graduate_count: graduateHits.length,
      course_record_count: courseRecordHits.length
    }
  };
}


 // ---------------- Top Market Skills Renderer ----------------
function renderTopSkills(data) {
  if (!isObject(data)) {
    return null;
  }

  // Support both direct tool results and nested MCP result envelopes.
  const payload =
    isObject(data.result) &&
    (
      data.result.analysis === "top_market_skills" ||
      Array.isArray(data.result.results)
    )
      ? data.result
      : data;

  if (
    !isObject(payload) ||
    !Array.isArray(payload.results) ||
    !payload.results.every(isObject)
  ) {
    return null;
  }

  if (
    payload.analysis !== undefined &&
    payload.analysis !== "top_market_skills"
  ) {
    return null;
  }

  const rows = payload.results.map((item) => ({
    skill: item.skill,
    average_demand_score: item.average_demand_score,
    total_frequency: item.total_frequency,
    record_count: item.record_count
  }));

  // Reject malformed records rather than silently displaying
  // incomplete or misleading analytical results.
  const requiredFields = [
    "skill",
    "average_demand_score",
    "total_frequency",
    "record_count"
  ];

  const hasValidRows = rows.every((row) =>
    requiredFields.every((field) =>
      row[field] !== undefined &&
      row[field] !== null
    ) &&
    safeNumber(row.average_demand_score) !== null &&
    safeNumber(row.total_frequency) !== null &&
    safeNumber(row.record_count) !== null
  );

  if (!hasValidRows) {
    return null;
  }

  const columns = [
    "skill",
    "average_demand_score",
    "total_frequency",
    "record_count"
  ];

  const totalRecords =
    safeNumber(payload.total_records) ?? rows.length;

  return {
    countValue: null,
    rowCount: rows.length,
    totalRecords,
    shown: Math.min(rows.length, MAX_SHOWN),
    columns,
    rows,
    tableMarkdown: rows.length
      ? markdownTable(columns, rows.slice(0, MAX_SHOWN))
      : "(هیچ مهارتی برنگشت)"
  };
}


// ---------------- Analytics COUNT Renderer ----------------
function renderCount(data) {
  if (!isObject(data)) {
    return null;
  }

  const candidate =
    data.result?.count ??
    data.count ??
    data.total ??
    data.total_records ??
    data.document_count ??
    data.value ??
    data.hits?.total?.value ??
    data.metadata?.total_records ??
    null;

  const count = safeNumber(candidate);

  if (
    count === null ||
    !Number.isInteger(count) ||
    count < 0
  ) {
    return null;
  }

  return {
    countValue: count,
    rowCount: 1,
    totalRecords: count,
    shown: 1,
    columns: ["count"],
    rows: [{ count }],
    tableMarkdown: `**تعداد رکوردهای منطبق: ${count}**`
  };
}


// ---------------- Analytics SELECT Renderer ----------------
function renderSelect(data, args) {
  let candidate = null;
  let total = null;

  if (Array.isArray(data)) {
    candidate = data;
  } else if (isObject(data)) {
    if (Array.isArray(data.result)) {
      candidate = data.result;
    } else if (Array.isArray(data.rows)) {
      candidate = data.rows;
    } else if (Array.isArray(data.records)) {
      candidate = data.records;
    } else if (Array.isArray(data.results)) {
      candidate = data.results;
    } else if (Array.isArray(data.hits)) {
      candidate = data.hits;
    } else if (
      isObject(data.hits) &&
      Array.isArray(data.hits.hits)
    ) {
      candidate = data.hits.hits;
    }

    total =
      data.metadata?.total_records ??
      data.total_records ??
      data.total ??
      data.hits?.total?.value ??
      null;
  }

  const rows = normalizeRows(candidate);

  if (!rows || !rows.every(isObject)) {
    return null;
  }

  const sortFields = Array.isArray(args?.sort)
    ? args.sort.map((item) => item.field).filter(Boolean)
    : [];

  const columns = getColumns(rows, sortFields);

  const totalRecords =
    safeNumber(total) ?? rows.length;

  return {
    countValue: null,
    rowCount: rows.length,
    totalRecords,
    shown: Math.min(rows.length, MAX_SHOWN),
    columns,
    rows,
    tableMarkdown: rows.length
      ? markdownTable(columns, rows.slice(0, MAX_SHOWN))
      : "(هیچ رکوردی برنگشت)"
  };
}


// ---------------- Analytics AGGREGATE Renderer ----------------
function flattenBucket(bucket, args) {
  const row = {};

  const groupBy = Array.isArray(args.group_by)
    ? args.group_by
    : [];

  for (const [key, value] of Object.entries(bucket)) {
    if (
      ![
        "group",
        "metrics",
        "document_count",
        "key",
        "doc_count",
        "key_as_string"
      ].includes(key)
    ) {
      row[key] = value;
    }
  }

  const addGroup = (group) => {
    if (isObject(group)) {
      Object.assign(row, group);
    } else if (group !== undefined && group !== null) {
      const field =
        groupBy.length === 1 ? groupBy[0] : "group";

      row[field] = group;
    }
  };

  addGroup(bucket.group);
  addGroup(bucket.key);

  if (bucket.key_as_string !== undefined && !groupBy.length) {
    row.group = bucket.key_as_string;
  }

  if (isObject(bucket.metrics)) {
    Object.assign(row, bucket.metrics);
  }

  const countMetric = (args.metrics ?? []).find(
    (metric) => metric.function === "count_documents"
  );

  const countAlias = countMetric?.alias ?? "record_count";

  if (bucket.document_count !== undefined) {
    row[countAlias] = bucket.document_count;
  } else if (bucket.doc_count !== undefined) {
    row[countAlias] = bucket.doc_count;
  }

  return row;
}



function renderAggregate(data, args) {
  let candidate = null;

  if (Array.isArray(data)) {
    candidate = data;

  } else if (isObject(data)) {

    // Direct bucket structures
    if (Array.isArray(data.buckets)) {
      candidate = data.buckets;

    // MCP response structure: data.result.buckets
    } else if (
      isObject(data.result) &&
      Array.isArray(data.result.buckets)
    ) {
      candidate = data.result.buckets;

    } else if (Array.isArray(data.groups)) {
      candidate = data.groups;

    } else if (Array.isArray(data.rows)) {
      candidate = data.rows;

    // Elasticsearch aggregation response
    } else if (isObject(data.aggregations)) {
      const aggregationValues = Object.values(
        data.aggregations
      );

      const bucketAggregation = aggregationValues.find(
        (value) =>
          isObject(value) &&
          Array.isArray(value.buckets)
      );

      if (bucketAggregation) {
        candidate = bucketAggregation.buckets;
      }
    }
  }

  if (
    !Array.isArray(candidate) ||
    !candidate.every(isObject)
  ) {
    return null;
  }

  const rows = candidate.map((bucket) =>
    flattenBucket(bucket, args)
  );

  const requiredColumns = [
    ...(Array.isArray(args?.group_by)
      ? args.group_by
      : []),

    ...(Array.isArray(args?.metrics)
      ? args.metrics
          .map((metric) => metric.alias)
          .filter(Boolean)
      : [])
  ];

  const missingColumns = requiredColumns.filter(
    (column) =>
      rows.some(
        (row) =>
          !isObject(row) ||
          !(column in row)
      )
  );

  if (missingColumns.length) {
    return null;
  }

  const columns = getColumns(
    rows,
    requiredColumns
  );

  return {
    countValue: null,
    rowCount: rows.length,
    totalRecords: rows.length,
    shown: Math.min(rows.length, MAX_SHOWN),
    columns,
    rows,
    tableMarkdown: rows.length
      ? markdownTable(columns, rows.slice(0, MAX_SHOWN))
      : "(هیچ گروهی برنگشت)"
  };
}



// ---------------- Additional Tool Result Renderer ----------------
function renderGenericTool(data) {
  if (Array.isArray(data)) {
    const rows = normalizeRows(data);

    if (!rows || !rows.every(isObject)) return null;

    const columns = getColumns(rows);

    return {
      countValue: null,
