      shown: Math.min(rows.length, MAX_SHOWN),
      columns,
      rows,
      tableMarkdown: markdownTable(columns, rows.slice(0, MAX_SHOWN))
    };
  }

  if (isObject(data)) {
    const candidate =
      data.rows ??
      data.results ??
      data.records ??
      null;

    if (Array.isArray(candidate)) {
      const rows = normalizeRows(candidate);

      if (!rows || !rows.every(isObject)) return null;

      const columns = getColumns(rows);

      return {
        countValue: null,
        rowCount: rows.length,
        totalRecords:
          safeNumber(
            data.total_records ??
