// Normalize a validated plan while preserving its metadata.
function normalizePlan(plan, index, total) {
  if (!plan || typeof plan !== "object" || Array.isArray(plan)) {
    throw new Error(`Invalid plan structure at index ${index}.`);
  }

  // Multi-plan validation may wrap the actual validated plan
  // inside an additional "plan" property.
  const validatedPlan =
    plan.plan &&
    typeof plan.plan === "object" &&
    !Array.isArray(plan.plan)
      ? plan.plan
      : plan;

  if (
    typeof validatedPlan.tool !== "string" ||
    !validatedPlan.tool.trim() ||
    !validatedPlan.arguments ||
    typeof validatedPlan.arguments !== "object" ||
    Array.isArray(validatedPlan.arguments)
  ) {
    throw new Error(
      `Malformed validated plan at index ${index}.`
    );
  }

  return {
    valid: true,
    errors: [],
    warnings: plan.warnings ?? [],
    attempt: item.attempt ?? 0,
    question: item.question,
    multi: total > 1,
    planId: plan.plan_id ?? plan.planId ?? `plan_${index + 1}`,
    planIndex: index,
    planCount: total,
    subQuestion:
      plan.sub_question ??
      plan.subQuestion ??
      item.question,
    plan: validatedPlan
  };
}

// If validation failed, pass the failure through unchanged.
if (!item.valid) {
  return [{ json: item }];
}

// Multi-plan mode
if (item.multi === true && Array.isArray(item.plans)) {
  if (item.plans.length === 0) {
    return [{
      json: {
        valid: false,
        errors: ["No validated plans were provided."],
        warnings: item.warnings ?? [],
        attempt: item.attempt ?? 0,
        question: item.question,
        multi: true,
        planCount: 0
      }
    }];
  }

  return item.plans.map((plan, index) => ({
    json: normalizePlan(
      plan,
      index,
      item.plans.length
    )
  }));
}

// Single-plan mode — backward compatible
if (!item.plan) {
  return [{
    json: {
      valid: false,
      errors: ["Validated plan is missing."],
      warnings: item.warnings ?? [],
      attempt: item.attempt ?? 0,
      question: item.question,
      multi: false,
      planCount: 1
    }
  }];
}

return [{
  json: normalizePlan(item.plan, 0, 1)
}];

